//! 完整P2子用例先定义，再以同一动作集扩展P4；不以人数跳过功能/故障。
use serde_json::{Value,json};
use crate::Result;
fn check(name:&str)->Value{json!({"op":"observe","check":name,"timeout_ms":30000,"expected":"real-source+native+precise-ACK;missing-is-incomplete"})}
fn fixture(action:&str)->Value{json!({"op":"observe","check":"host-fixture-action","action":action,"trigger":"physical-F8","timeout_ms":30000,"host_only":true})}
fn case(id:&str,label:&str,load:&str,steps:Vec<Value>,checks:&[&str])->Value{
 let mut p2=steps.clone();p2.extend(checks.iter().map(|s|check(s)));let p4=p2.clone();
 json!({"id":format!("{id}.{label}"),"e":id,"initial":{"load":load,"network":"N0","clients":"all-before-run;frozen-identities","room":"Basement ordinary debug room d.10;entity spawn seed starts212121;record actual run seed","resources":"official REPENTOGON1.1.3/J273 and supported18-20"},"p2":p2,"p4":p4,"timeout_ms":240000,"cleanup":"release-all-physical;N0;disarm-faults;safe-retirement-on-failure","p4_extra":["three-peer-fairness","healthy-clients-continue","four-groups-eight-bodies-when-dual"],"pass_requires_all_steps":true})
}
fn network(profile:&str,ms:u64)->Value{json!({"op":"network","profile":profile,"peer":0,"duration_ms":ms})}
fn window(load:&str,ms:u64,combat:u64)->Value{json!({"op":"sample","load":load,"duration_ms":ms,"combat_ms":combat,"mark":"stable-fixed-before-start","exclude_only":["declared-host-pause","declared-structural-transaction","visual-neutral"],"retain_network_failures_in_denominator":true})}
// 负载必须在实际Host成员/更新/受击见证中成立；夹具声明不替代最低数量。
pub fn loads()->Value{json!({
 "L0a":{"participants":2,"active_bodies":2,"npc_min":8,"attack_min":16,"stable_ms":180000,"combat_ms":60000},
 "L0b":{"participants":2,"active_bodies":4,"type_pair":[19,20],"npc_min":8,"attack_min":16,"stable_ms":180000,"combat_ms":60000},
 "L0c":{"participants":2,"root_types":[19,29],"backup":true,"stable_ms":60000},
 "L1":{"participants":4,"active_bodies":4,"npc_min":8,"attack_min":32,"stable_ms":180000,"combat_ms":60000},
 "L2":{"participants":4,"active_bodies":8,"type_pair":[19,20],"npc_min":8,"attack_min":32,"stable_ms":180000,"combat_ms":60000},
 "L3":{"participants":4,"root_types":[0,19,16,29],"backup":true,"stable_ms":60000},
 "L4":{"base":"L2-or-L0b","slow_bps":500000,"damage_ms":30000,"recovery_ms":60000},
 "budget":{"total_byte_s":937500,"peer_byte_s":312500,"proxy_total_byte_s":1250000,"burst":24576,"peer_burst":8192,"cross_peer_borrow":false}})}

pub fn suite()->Vec<Value>{let mut out=Vec::new();
 for mismatch in ["wire","stream-schema","compact-schema","resource-declaration","session-identity","framing","capability-missing","full-room-capacity"]{out.push(case("E01",mismatch,"menu",vec![json!({"op":"network","negative":mismatch,"from_real":"Hello/Welcome","max_hits":1})],&["negotiation-refused-before-large-allocation","identity-not-reused"]))}
 out.push(case("E01","valid-menu","menu",vec![],&["menu-real-network-connected","frozen-participant-identity","effective-config-fixed-p2-share"]));
 out.push(case("E02","cold","L0a",vec![fixture("ordinary"),check("cold-cache-empty"),check("network-baseline-no-file-import")],&["same-version-full-native-and-visual","ACK-after-native-commit","cold-all-dependencies-1MiB-and-10s"]));
 for load in ["L0a","L0b"]{out.push(case("E03",load,load,vec![fixture(if load=="L0a"{"ordinary"}else{"dual"}),window(load,180000,60000)],&["actual-load-through-stable-window","frequency-coverage-gap-cpu-bandwidth-contract"]));}
 for load in ["L0a","L0b","L0c"]{out.push(case("E04",load,load,vec![fixture(match load{"L0a"=>"ordinary","L0b"=>"dual",_=>"mixed"})],&["each-group-real-input-and-native-consumer","complete-members-relations-resources","absent-body-not-fake60Hz"]));}
 for action in ["combat","laser","bomb-grid","door"]{out.push(case("E05",action,"L0a",vec![fixture(action),window("L0a",10000,10000)],&["natural-damage-and-removal","same-version-full-native-and-visual","client-no-second-judgement"]));}
 for action in ["pickup","resources","create-remove","zero-empty","last-static"]{out.push(case("E06",action,"L0a",vec![fixture(action)],&["explicit-null-zero-empty-deletion","final-state-500ms-N0","same-version-full-native-and-visual"]));}
 for action in ["costume","weapon","shape","backup","forgotten","missing-resource","old-definition"]{out.push(case("E07",action,"L0c",vec![fixture(action)],&["structure-version-resource-retirement","same-version-full-native-and-visual","failure-first-cause-preserved"]));}
 for ordinal in 0..2{for action in ["move","opposite-shoot-last-wins","release-fallback","bomb","active","card-pill","drop"]{out.push(case("E08",&format!("p{ordinal}-{action}"),"L0b",vec![json!({"op":"observe","check":"physical-input-script","participant":ordinal,"script":action,"timeout_ms":30000,"require":"physical-source+canonical+ordinary/odd-body-consumer;edges-exactly-once"})],&["input-lead2-age0-and-no-roster-throttle","actual-input-consumers-and-edges"]));}}
 for state in ["host-pause","host-console","client-focus","client-ui"]{out.push(case("E08",state,"L0b",vec![json!({"op":"human","instruction":format!("开始{state}操作；按提示恢复后立即停止手动操作，由编排器接管")})],&["pause-neutral-no-edge-replay","input-recovery-real-consumer"]));}
 for version in ["baseline","ordinary","player-post","odd-interleave","structure","recovery"]{out.push(case("E09",version,"L0b",vec![json!({"op":"observe","check":"align-version","kind":version,"timeout_ms":30000})],&["source-dto-native-field-by-field","retained-vs-applied-domain-exact","render-version-visual-reviewed"]));}
 out.push(case("E10","N1","L0b",vec![network("N1",120000),window("L0b",120000,60000)],&["all-random-faults-actually-hit","bounded-transfer-convergence","N1-state-age"]));
 for fault in ["first-fragment","middle-fragment","last-fragment","receive-ack","applied-ack","duplicate","reorder"]{out.push(case("E10",fault,"L0b",vec![json!({"op":"network","profile":"N2","fault":fault,"peer":0,"max_hits":1,"from_real":"selected-baseline-transfer"})],&["fault-actually-hit","selective-retransmit-billed","incomplete-no-native-no-applied","final-state-converged"]));}
 for ack in ["ReceiveAck","AppliedAck","OperationAck"]{out.push(case("E11",ack,"L0a",vec![json!({"op":"network","drop_kind":ack,"peer":0,"max_hits":1})],&["ACK-repeat-only-no-native-repeat","confirmation-stages-distinct"]));}
 for profile in ["downlink-2s","slow-0.5Mbps-30s","entity-overload"]{out.push(case("E12",profile,"L0b",vec![network(profile,if profile=="downlink-2s"{2000}else{30000}),window("L4",30000,30000),network("N0",0),window("recovered",60000,60000)],&["host-and-healthy-peers-progress","queue-pools-bounded","control-input-not-starved","same-connection-latest-baseline-or-independent-stop"]));}
 for bad in ["old-route","wrong-connection","wrong-transfer","same-fragment-conflict","same-sequence-different-value","future-ACK","unsent-ACK","cross-peer"]{out.push(case("E13",bad,"L0a",vec![json!({"op":"network","negative":bad,"from_real":"current-peer-datagram","max_hits":1})],&["actual-rejection-reason","current-state-and-input-unpolluted"]));}
 for stage in ["initial-prepare","recovery"]{for old in ["old-input","old-ACK","old-fragment","missing-context","cancel-transfer"]{out.push(case("E14",&format!("{stage}-{old}"),"L0a",vec![json!({"op":"network","phase":stage,"negative":old,"max_hits":1})],&["old-scope-cannot-revive","dependencies-exact-no-deadlock"]));}}
 for point in ["missing-field","missing-resource","acquire-before","acquire-after","init-before","init-after","fields-before","fields-after","resources-before","resources-after","publish-before","publish-after","references-before","references-after","check-before","check-after","draw-before","draw-after"]{out.push(case("E15",point,"L0a",vec![json!({"op":"observe","check":"arm-native-fault","point":point,"timeout_ms":30000})],&["fault-actually-hit","prewrite-A-or-postwrite-stop-display","half-state-no-ACK","safe-retire-and-one-new-baseline-recovery"]));}
 for stem in ["allocate","ctor","init","fields","resources","hud","roster","publish","weapon","relations","check","draw"]{for side in ["before","after"]{out.push(case("E15",&format!("player-{stem}-{side}"),"L0b",vec![json!({"op":"observe","check":"arm-player-fault","point":format!("player-{stem}-{side}"),"timeout_ms":30000})],&["fault-actually-hit","player-prefix-owner-preserved","safe-retire-and-one-new-baseline-recovery"]));}}
 for stage in ["prepare","transfer","apply","display"]{for why in ["client-stop","host-stop","network-error","window-close"]{out.push(case("E16",&format!("{stage}-{why}"),"L0a",vec![json!({"op":"observe","check":"stop-at-real-stage","stage":stage,"cause":why,"timeout_ms":30000})],&["input-and-publication-closed","actual-native-retired-before-Off","hooks-resident-logical-stop"]));}}
 for malformed in ["length","count","reserved","version","compressed-frame","compressed-window","decompress-limit","candidate-flood","fake-identity","fragment-overflow","nested-depth","duplicate-field"]{out.push(case("E17",malformed,"L0a",vec![json!({"op":"network","negative":malformed,"from_real":"captured-current-message","max_hits":20})],&["bounded-specific-rejection","host-and-healthy-peers-progress","local-limits-not-raised"]));}
 out.push(case("E18","recorder-off","L0a",vec![json!({"op":"command","node":"host","text":"cs observe off"}),window("L0a",60000,60000)],&["formal-source-without-recorder","one-shared-scan-not-per-peer","diagnostics-failure-independent"]));
 for phase in ["prepare","construct","dynamic","draw","recover","retire"]{out.push(case("E19",phase,"L0a",vec![json!({"op":"observe","check":"full-window-isolation","phase":phase,"timeout_ms":30000})],&["no-client-gameplay-random-persistence","calls-plus-final-files-observed"]));}
 out.push(case("E20","natural-interaction","L0a",vec![json!({"op":"human","instruction":"自然互动至少60秒：各参与者移动、射击、受击与拾取；结束信号后停止手动操作，由编排器收尾"}),window("natural",60000,60000)],&["real-physical-60s","same-authority-feedback-all-windows","render-version-visual-reviewed"]));
 for action in ["long-stable","overload","resource-repeat","target-repeat20"]{out.push(case("E21",action,"L0b",vec![fixture(if action=="resource-repeat"{"costume"}else{"dual"}),window("L0b",180000,60000),json!({"op":"observe","check":"repeat-latest-exact-target","count":20,"timeout_ms":30000})],&["no-growth-or-construction-repeat","no-cancellation-starvation","frequency-coverage-gap-cpu-bandwidth-contract"]));}
 for life in ["resource-generation","failed-retire","old-instance","lua-generation","context-generation","second-native-failure","unknown-owner"]{out.push(case("E22",life,"L0c",vec![json!({"op":"observe","check":"lifetime-fault","kind":life,"timeout_ms":30000})],&["no-expired-borrow","first-cause-and-owner-kept","recover-latest-or-retain-isolation"]));}
 for flavor in ["product","e2e"]{for dependency in ["normal","missing-runtime","missing-version","missing-resource"]{out.push(case("E23",&format!("{flavor}-{dependency}"),"menu",vec![json!({"op":"observe","check":"deployment","flavor":flavor,"dependency":dependency,"timeout_ms":30000})],&["matching-built-dll-catalog-static-zstd","accurate-load-error-or-success","product-no-test-entry"]));}}
 out.push(case("E24","product-network","L0a",vec![check("product-restart-without-fixture"),json!({"op":"human","instruction":"产品DLL：连接后实际移动、射击，再按提示停止；不加载测试夹具"})],&["product-real-network-input-display-stop","default-no-detail-logs-ui-only"]));
 // I37把全部受影响18-20条目展开到此列表；不得以旧离线PASS替代本次网络执行。
 for contract in ["room-grid-source-positive-negative","entity-source-all-classes-variants","player-C01-C17-all-bodies","resources-and-failure-prefixes","input-lifecycle-regression"]{out.push(case("E25",contract,"L0c",vec![json!({"op":"observe","check":"network-regression-catalog","catalog":contract,"expand_all":true,"timeout_ms":240000})],&["all-affected-positive-negative-completed-in-real-network"]));}
 out.push(case("E26","reduce-and-restore","none",vec![],&["every-case-and-subcase-complete","all-metrics-and-visuals-reviewed","first-failures-and-retests-preserved","safe-stop-and-environment-restored"]));out
}
// 具体人数和负载扩展在执行前固定；P2中的参与者循环扩大为四组，功能子项保持完整。
pub fn phase_suite(phase:&str)->Result<Vec<Value>>{if phase!="p2"&&phase!="p4"{return Err("tx21_phase".into())}let mut cases=suite();if phase=="p4"{let extra=cases.iter().filter(|c|c["e"]=="E08"&&c["id"].as_str().is_some_and(|s|s.contains(".p0-"))).cloned().collect::<Vec<_>>();for ordinal in [2,3]{for mut c in extra.clone(){let id=c["id"].as_str().unwrap().replace(".p0-",&format!(".p{ordinal}-"));c["id"]=json!(id);for s in c["p4"].as_array_mut().unwrap(){if s["participant"]==0{s["participant"]=json!(ordinal)}}cases.push(c)}}for c in &mut cases{if let Some(load)=c["initial"]["load"].as_str(){let mapped=match load{"L0a"=>"L1","L0b"=>"L2","L0c"=>"L3",other=>other}.to_owned();c["initial"]["load"]=json!(mapped);}for s in c["p4"].as_array_mut().unwrap(){if let Some(load)=s["load"].as_str(){s["load"]=json!(match load{"L0a"=>"L1","L0b"=>"L2","L0c"=>"L3",other=>other})}}}}Ok(cases)}
